const size_t N = 10;

// UNSAFE: Loop is infinite because i >= 0 is always true
// for (size_t i = N; i >= 0; --i) {}

// SAFE Pattern 1: Post-decrement check
// i iterates N-1 down to 0
for (size_t i = N; i-- > 0; ) {
    // Use i here
}

// SAFE Pattern 2: Pre-decrement inside while loop
size_t j = N;
while (j > 0) {
    j--; // J is N-1 down to 0
}
